const d = $input.first().json;
const u = d.update || {};
const cb = String(u.callback_query?.data ?? '');
const texto = String(u.message?.text ?? '').trim();
const chat = u.callback_query?.message?.chat?.id ?? u.message?.chat?.id;
const tel = String(d.telefono_api || d.telefono || '').replace(/\D/g, '').slice(-9);
return [{ json: Object.assign({}, d, { cb: cb, texto: texto, chat: String(chat), queryId: String(u.callback_query?.id ?? ''), tel: tel }) }];

const p = $('Preparar').first().json;
const t = p.t || {};
const hoy = $now.toFormat('yyyy-MM-dd');
const filas = $input.all().map(i => i.json).filter(r => r.id && r.estado !== 'borrador' && String(r.creado || '').slice(0, 10) === hoy);
filas.sort((a, b) => String(b.creado || '').localeCompare(String(a.creado || '')));
const top = filas.slice(0, 15);
let texto;
if (!top.length) {
  texto = t.cab_mis_vacio;
} else {
  texto = t.cab_mis_titulo + '\n\n' + top.map(r => {
    const est = t['cab_est_' + r.estado] || r.estado;
    const f = String(r.creado || '').slice(11, 16);
    return '• ' + f + ' · ' + r.matricula_tractora + ' / ' + r.matricula_remolque + ' · ' + r.palets + ' 📦\n   ' + est + (r.movimiento ? ' · Mov. ' + r.movimiento : '') + (r.deca ? ' · ' + r.deca : '') + (r.deca_url ? '\n   🔗 ' + r.deca_url : '');
  }).join('\n\n');
}
return [{ json: { texto: texto } }];

const p = $('Preparar').first().json;
const t = p.t || {};
const f = $input.first().json || {};
const chat = p.chat;
if (!f.id || f.estado !== 'borrador') return [{ json: { accion: 'sin_borrador', chat: chat } }];
const conductor = String(p.conductor_id || f.conductor_id || '').trim();
const out = { id: f.id, chat: chat, tractora: f.matricula_tractora || '', remolque: f.matricula_remolque || '', palets: f.palets || 0, conductor: conductor, paso: f.paso, accion: '', mensaje: '' };
const resumen = () => String(t.cab_resumen || '').replace('{tractora}', out.tractora).replace('{remolque}', out.remolque).replace('{palets}', String(out.palets));
const fin = (accion, mensaje) => { out.accion = accion; out.mensaje = mensaje; return [{ json: out }]; };
const norm = (s) => String(s).toUpperCase().replace(/[\s-]/g, '');
const okMat = (s) => /^[A-Z0-9]{4,10}$/.test(s);
if (p.cb === 'cab_ok') {
  if (f.paso !== 'confirmar') return [{ json: { accion: 'sin_borrador', chat: chat } }];
  if (!conductor) return fin('sin_codigo', '');
  return fin('confirmar', '');
}
const txt = p.texto;
if (f.paso === 'tractora') {
  const m = norm(txt);
  if (!okMat(m)) return fin('repetir', t.cab_err_matricula + '\n\n' + t.cab_pedir_tractora);
  out.tractora = m; out.paso = 'remolque';
  return fin('avanzar', t.cab_pedir_remolque);
}
if (f.paso === 'remolque') {
  const m = norm(txt);
  if (!okMat(m)) return fin('repetir', t.cab_err_matricula + '\n\n' + t.cab_pedir_remolque);
  out.remolque = m; out.paso = 'palets';
  return fin('avanzar', t.cab_pedir_palets);
}
if (f.paso === 'palets') {
  const n = /^\d{1,3}$/.test(txt) ? parseInt(txt, 10) : 0;
  if (n < 1 || n > 66) return fin('repetir', t.cab_err_palets + '\n\n' + t.cab_pedir_palets);
  out.palets = n; out.paso = 'confirmar';
  return fin('resumen', resumen());
}
return fin('resumen', resumen());

const r = $input.first().json || {};
const status = Number(r.statusCode || 0);
const rawv = r.data !== undefined ? r.data : (r.body !== undefined ? r.body : (r.error || ''));
let body = rawv;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) {} }
const b = (body && typeof body === 'object' && !Array.isArray(body)) ? body : {};
const s = (v) => (v === undefined || v === null) ? '' : String(v);
const ok = status >= 200 && status < 300 && b.success !== false && !b.error;
const raw = typeof rawv === 'string' ? rawv : JSON.stringify(rawv);
const mensaje = [b.info, b.aviso, b.message, b.mensaje, b.error].map(s).filter(x => x).join(' | ') || s(r.error && (r.error.message || r.error));
return [{ json: { ok: ok, status: status, pedido: s(b.pedido), movimiento: s(b.movimiento), deca: s(b.deca), deca_url: s(b.pdf), aviso: s(b.aviso), mensaje: mensaje.slice(0, 300), raw: raw.slice(0, 400) } }];

const p = $('Preparar').first().json;
const t = p.t || {};
const r = $('Procesar respuesta').first().json;
let texto = String(t.cab_creado || '').replace('{pedido}', r.pedido || '-').replace('{movimiento}', r.movimiento || '-').replace('{deca}', r.deca || '-');
if (r.deca_url) texto += '\n\n🔗 ' + r.deca_url;
return [{ json: { texto: texto, pdf: r.deca_url } }];

